function findMin(nums) {
    let l = 0, r = nums.length - 1;
    while (l < r) {
        let mid = (l + r) >> 1;
        if (nums[mid] > nums[r]) {
            l = mid + 1;
        }
        else if (nums[mid] == nums[r]) {
            r--;
        }
        else {
            r = mid;
        }
    }
    return nums[l];
}

